class NoRaSetupAttemptsDetected(Exception):
    """
    Raised when there are no RA Setup Attempts detected for contention based group A preambles corresponding to
    any SSB beam ID found on setup in BTS Counters (To find out more please check M55306C00001-M55306C00XXX counters
    on BTS).
    """
    pass


class NoRaSetupCompletionsDetected(Exception):
    """
    Raised when there are no RA Setup Completions detected for contention based group A preambles (To find out more
    please check M55306C03001 counter on BTS).
    """
    pass


class InvalidRaMsg3ReceptionsNumber(Exception):
    """
    Raised when number of RA msg3 receptions counters are not consistent with expected number provided by user
    (To find out more please check M55306C06001 counter on BTS).
    """
    pass
